#include "OAGDStaticAssets.h"
#include "OAGDComponents.h"
#include "ProceduralMeshComponent.h"
#include "Engine/StaticMesh.h"
#include "StaticMeshResources.h"
#include "PhysicsEngine/BodySetup.h"
#include "Materials/MaterialInterface.h"
#include "Serialization/JsonSerializer.h"
FString UOAGDStaticAssets::InspectMesh(UStaticMesh* Mesh){
 auto R=MakeShared<FJsonObject>();R->SetBoolField(TEXT("valid"),Mesh!=nullptr);if(Mesh){R->SetStringField(TEXT("path"),Mesh->GetPathName());TArray<TSharedPtr<FJsonValue>> Lods,Materials;const auto* Data=Mesh->GetRenderData();if(Data)for(int32 LODIndex=0;LODIndex<Data->LODResources.Num();++LODIndex){const auto& L=Data->LODResources[LODIndex];auto J=MakeShared<FJsonObject>();J->SetNumberField(TEXT("triangles"),L.GetNumTriangles());J->SetNumberField(TEXT("screen_size"),Data->ScreenSize[LODIndex].GetValue());J->SetNumberField(TEXT("vertices"),L.GetNumVertices());Lods.Add(MakeShared<FJsonValueObject>(J));}R->SetArrayField(TEXT("lods"),Lods);
 for(int I=0;I<Mesh->GetStaticMaterials().Num();++I){auto J=MakeShared<FJsonObject>();auto* M=Mesh->GetMaterial(I);J->SetStringField(TEXT("slot"),Mesh->GetStaticMaterials()[I].MaterialSlotName.ToString());J->SetStringField(TEXT("material"),M?M->GetPathName():TEXT(""));FLinearColor C=FLinearColor::Black;float Rough=0,Metal=0;bool Valid=M&&M->GetVectorParameterValue(FMaterialParameterInfo(TEXT("BaseColor")),C)&&M->GetScalarParameterValue(FMaterialParameterInfo(TEXT("Roughness")),Rough)&&M->GetScalarParameterValue(FMaterialParameterInfo(TEXT("Metallic")),Metal);J->SetBoolField(TEXT("parameters_read"),Valid);J->SetArrayField(TEXT("color"),{MakeShared<FJsonValueNumber>(C.R),MakeShared<FJsonValueNumber>(C.G),MakeShared<FJsonValueNumber>(C.B),MakeShared<FJsonValueNumber>(C.A)});J->SetNumberField(TEXT("roughness"),Rough);J->SetNumberField(TEXT("metallic"),Metal);Materials.Add(MakeShared<FJsonValueObject>(J));}R->SetArrayField(TEXT("materials"),Materials);
 auto B=Mesh->GetBoundingBox();auto Convert=[](FVector V){return TArray<TSharedPtr<FJsonValue>>{MakeShared<FJsonValueNumber>(V.X/100),MakeShared<FJsonValueNumber>(V.Z/100),MakeShared<FJsonValueNumber>(V.Y/100)};};R->SetArrayField(TEXT("bounds"),{MakeShared<FJsonValueArray>(Convert(B.Min)),MakeShared<FJsonValueArray>(Convert(B.Max))});
 R->SetBoolField(TEXT("complex_collision"),Mesh->GetBodySetup()&&Mesh->GetBodySetup()->CollisionTraceFlag==CTF_UseComplexAsSimple);R->SetNumberField(TEXT("collision_lod"),Mesh->LODForCollision);}
 FString Text;FJsonSerializer::Serialize(R,TJsonWriterFactory<>::Create(&Text));return Text;
}
bool UOAGDStaticAssets::GeometryMatches(AOAGDGeometry* A,const FString& Text){if(!A||!A->GetActorTransform().Equals(FTransform::Identity))return false;TSharedPtr<FJsonObject> R;if(!FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Text),R))return false;const auto* Section=A->Geometry->GetProcMeshSection(0);auto P=R->GetArrayField(TEXT("positions"));if(!Section||Section->ProcVertexBuffer.Num()!=P.Num())return false;for(int I=0;I<P.Num();++I){auto V=P[I]->AsArray();FVector Expected(-V[2]->AsNumber()*100,V[0]->AsNumber()*100,V[1]->AsNumber()*100);if(!Section->ProcVertexBuffer[I].Position.Equals(Expected,.01))return false;}auto Indices=R->GetArrayField(TEXT("indices"));if(Section->ProcIndexBuffer.Num()!=Indices.Num())return false;for(int I=0;I<Indices.Num();++I)if(Section->ProcIndexBuffer[I]!=(uint32)Indices[I]->AsNumber())return false;auto Normals=R->GetArrayField(TEXT("normals"));auto Color=R->GetArrayField(TEXT("color"));FColor ExpectedColor=FLinearColor(Color[0]->AsNumber(),Color[1]->AsNumber(),Color[2]->AsNumber(),Color[3]->AsNumber()).ToFColor(false);for(int I=0;I<Normals.Num();++I){auto N=Normals[I]->AsArray();FVector Expected(-N[2]->AsNumber(),N[0]->AsNumber(),N[1]->AsNumber());if(!Section->ProcVertexBuffer[I].Normal.Equals(Expected,.001)||Section->ProcVertexBuffer[I].Color!=ExpectedColor)return false;}return true;}
